#include "retrieve.h"

#include "unicode_tables.h"

#include <math.h>
#include <stdlib.h>
#include <string.h>

/* ---------------------------------------------------------------- fold */

/* The fold itself is `tt_fold_ascii` in `unicode_tables.h`, generated by
 * `tools/ucd` from the Unicode database: lowercase, canonical decomposition,
 * marks dropped, and what survives kept only if it is one ASCII letter or
 * digit.  It is generated and not written by hand because the hand-written
 * version was WRONG in a way nothing announced -- it covered Latin-1 and
 * Latin Extended-A, which is all Portuguese needs, and silently cut every
 * transliterated citation the books make in half: "puruṣa" indexed as "puru",
 * "upaniṣad" as "upani", "satipaṭṭhāna" as "satipa".  Four terms of vocabulary
 * apart from the reference, and the only symptom would have been that asking
 * about the Upanishads retrieved nothing. */

/* Portuguese function words: no discriminative signal, and they dominate raw
 * term frequency.  Folded and sorted for binary search; entries of two bytes or
 * fewer are absent because the length filter removes them first, which is the
 * same composition the reference applies.  Kept identical to the STOP set of
 * `finetune/scripts/retrieve.py` -- the list that built the training data. */
static const char *const stop_words[] = {
    "ainda", "aos", "apenas", "apos", "aquela", "aquelas", "aquele",
    "aqueles", "aquilo", "assim", "ate", "com", "como", "das", "dos", "ela",
    "elas", "ele", "eles", "entao", "entre", "era", "eram", "essa", "essas",
    "esse", "esses", "esta", "estas", "este", "estes", "foi", "foram",
    "havia", "isso", "isto", "lhe", "lhes", "mais", "mas", "menos", "mesma",
    "mesmo", "meu", "minha", "muito", "nao", "nas", "nem", "nos", "nossa",
    "nosso", "onde", "outra", "outras", "outro", "outros", "para", "pela",
    "pelas", "pelo", "pelos", "pois", "por", "porque", "pouco", "quais",
    "qual", "quando", "quanto", "que", "sao", "sem", "sendo", "ser", "sera",
    "serao", "seu", "seus", "sido", "sob", "sobre", "sua", "suas", "tambem",
    "tem", "tinha", "toda", "todas", "todo", "todos", "uma", "umas", "uns",
    "vos"
};

#define N_STOP ((int)(sizeof(stop_words) / sizeof(stop_words[0])))

/* Longest term kept.  The folded form is never longer than the source run, and
 * a 64-byte run of letters does not occur in prose; a longer one is truncated,
 * consistently on both sides, so it still matches itself. */
#define TERM_MAX 64

static int cmp_str(const char *a, size_t an, const char *b, size_t bn)
{
    const size_t m = an < bn ? an : bn;
    const int c = m ? memcmp(a, b, m) : 0;
    if (c) return c;
    return an < bn ? -1 : (an > bn ? 1 : 0);
}

static int is_stop(const char *w, size_t n)
{
    int lo = 0, hi = N_STOP;
    while (lo < hi) {
        const int mid = lo + (hi - lo) / 2;
        const char *s = stop_words[mid];
        const int c = cmp_str(s, strlen(s), w, n);
        if (c == 0) return 1;
        if (c < 0) lo = mid + 1; else hi = mid;
    }
    return 0;
}

/* One codepoint.  An invalid byte advances one and reads as a separator: the
 * corpus is checked for strict UTF-8 when the index is built, so this path is
 * for a malformed QUERY, where refusing to crash matters more than being
 * exact. */
static int utf8_next(const char *s, size_t n, uint32_t *cp)
{
    const unsigned char *p = (const unsigned char *)s;
    if (p[0] < 0x80)                      { *cp = p[0];             return 1; }
    if ((p[0] & 0xE0) == 0xC0 && n >= 2 && (p[1] & 0xC0) == 0x80) {
        *cp = ((uint32_t)(p[0] & 0x1F) << 6) | (p[1] & 0x3F);       return 2;
    }
    if ((p[0] & 0xF0) == 0xE0 && n >= 3 && (p[1] & 0xC0) == 0x80
                                        && (p[2] & 0xC0) == 0x80) {
        *cp = ((uint32_t)(p[0] & 0x0F) << 12) | ((uint32_t)(p[1] & 0x3F) << 6)
            | (p[2] & 0x3F);                                        return 3;
    }
    if ((p[0] & 0xF8) == 0xF0 && n >= 4 && (p[1] & 0xC0) == 0x80
                                        && (p[2] & 0xC0) == 0x80
                                        && (p[3] & 0xC0) == 0x80) {
        *cp = ((uint32_t)(p[0] & 0x07) << 18) | ((uint32_t)(p[1] & 0x3F) << 12)
            | ((uint32_t)(p[2] & 0x3F) << 6) | (p[3] & 0x3F);       return 4;
    }
    *cp = 0xFFFD;
    return 1;
}

/* Returns the folded ASCII byte, or 0 for a separator.  `skip` means neither:
 * the codepoint contributes nothing and does NOT end the term. */
static int fold_cp(uint32_t cp, int *skip)
{
    const int c = tt_fold_ascii(cp);
    if (c) { *skip = 0; return c; }
    *skip = tt_is_mark(cp);
    return 0;
}

void tt_tokenize(const char *text, size_t len,
                 void (*fn)(const char *term, size_t n, void *ud), void *ud)
{
    char term[TERM_MAX];
    size_t n = 0, i = 0;

    /* `i <= len` on purpose: the extra round flushes a term that runs to the
     * end of the text, which is otherwise silently lost. */
    while (i <= len) {
        int c = 0, skip = 0;
        if (i < len) {
            uint32_t cp;
            i += (size_t)utf8_next(text + i, len - i, &cp);
            c = fold_cp(cp, &skip);
        } else {
            i++;
        }
        if (skip) continue;

        if (c) {
            if (n < TERM_MAX) term[n] = (char)c;
            n++;
            continue;
        }
        if (n > 2) {
            const size_t k = n < TERM_MAX ? n : TERM_MAX;
            if (!is_stop(term, k)) fn(term, k, ud);
        }
        n = 0;
    }
}

size_t tt_fold_term(const char *s, size_t n, char *out, size_t cap)
{
    size_t got = 0, i = 0;
    while (i < n && got + 1 < cap) {
        uint32_t cp;
        int skip;
        i += (size_t)utf8_next(s + i, n - i, &cp);
        const int c = fold_cp(cp, &skip);
        if (skip) continue;
        if (!c) break;
        out[got++] = (char)c;
    }
    out[got] = '\0';
    return got;
}

/* --------------------------------------------------------------- header */

static uint32_t get_u32(const unsigned char *p)
{
    return (uint32_t)p[0] | ((uint32_t)p[1] << 8)
         | ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
}

static uint64_t get_u64(const unsigned char *p)
{
    return (uint64_t)get_u32(p) | ((uint64_t)get_u32(p + 4) << 32);
}

/* Every section is checked before a single pointer is taken.  The rule is the
 * one docs/14 states for the container: a file that gets past the reader can be
 * walked without further checking, so a corrupt index fails at open with a
 * message, never mid-search with a fault. */
static int section(const tt_map *m, const unsigned char *h, size_t at,
                   size_t elem, uint64_t *off, uint64_t *count, const char *what)
{
    *off = get_u64(h + at);
    const uint64_t len = get_u64(h + at + 8);

    if (*off % TT_INDEX_ALIGN)
        return tt_fail(".ttindex: %s is not aligned to %u", what, TT_INDEX_ALIGN);
    if (*off > m->size || len > m->size - *off)
        return tt_fail(".ttindex: %s runs past the end of the file", what);
    if (elem && len % elem)
        return tt_fail(".ttindex: %s is %llu bytes, not a multiple of %llu",
                       what, (unsigned long long)len, (unsigned long long)elem);
    *count = elem ? len / elem : len;
    return 0;
}

int tt_index_open(tt_index *ix, const char *path)
{
    memset(ix, 0, sizeof(*ix));
    if (tt_map_open(&ix->map, path) != 0) return -1;

    if (ix->map.size < TT_INDEX_HEADER) {
        tt_map_close(&ix->map);
        return tt_fail("%s is too small to be a .ttindex", path);
    }

    const unsigned char *h = (const unsigned char *)ix->map.base;
    if (memcmp(h, TT_INDEX_MAGIC, 8) != 0) {
        tt_map_close(&ix->map);
        return tt_fail("%s is not a .ttindex (bad magic)", path);
    }

    const uint32_t version = get_u32(h + 8);
    if (version != TT_INDEX_VERSION) {
        tt_map_close(&ix->map);
        return tt_fail("%s is .ttindex v%u, this build reads v%u -- rebuild it "
                       "with tools\\index.exe", path, version, TT_INDEX_VERSION);
    }

    ix->n_docs  = get_u32(h + 12);
    ix->n_terms = get_u32(h + 16);
    const uint64_t total_len = get_u64(h + 24);

    uint64_t t_off, t_n, s_off, s_n, p_off, p_n, d_off, d_n, x_off, x_n;
    if (section(&ix->map, h, 32,  sizeof(tt_ix_term), &t_off, &t_n, "the term table")   != 0 ||
        section(&ix->map, h, 48,  1,                  &s_off, &s_n, "the string blob")  != 0 ||
        section(&ix->map, h, 64,  sizeof(tt_ix_post), &p_off, &p_n, "the postings")     != 0 ||
        section(&ix->map, h, 80,  sizeof(tt_ix_doc),  &d_off, &d_n, "the document table") != 0 ||
        section(&ix->map, h, 96,  1,                  &x_off, &x_n, "the text blob")    != 0) {
        tt_map_close(&ix->map);
        return -1;
    }

    if (t_n != ix->n_terms || d_n != ix->n_docs) {
        tt_map_close(&ix->map);
        return tt_fail(".ttindex: header says %u terms and %u docs, tables hold "
                       "%llu and %llu", ix->n_terms, ix->n_docs,
                       (unsigned long long)t_n, (unsigned long long)d_n);
    }
    if (!ix->n_docs || !ix->n_terms) {
        tt_map_close(&ix->map);
        return tt_fail(".ttindex: empty index (%u docs, %u terms)",
                       ix->n_docs, ix->n_terms);
    }
    /* A hit carries a signed document id, so the table cannot be larger than
     * one.  Unreachable with a real corpus; it is here so the cast below is
     * justified by a check and not by an assumption. */
    if (ix->n_docs > 0x7FFFFFFFu) {
        tt_map_close(&ix->map);
        return tt_fail(".ttindex: %u documents does not fit a signed id",
                       ix->n_docs);
    }
    /* Both blobs are returned to the caller as C strings, so the last byte has
     * to be a terminator -- otherwise a truncated file turns into a read past
     * the mapping the first time a title is printed. */
    const char *base = (const char *)ix->map.base;
    if (!s_n || base[s_off + s_n - 1] || !x_n || base[x_off + x_n - 1]) {
        tt_map_close(&ix->map);
        return tt_fail(".ttindex: the string or text blob is not terminated");
    }

    ix->terms   = (const tt_ix_term *)(const void *)(base + t_off);
    ix->strings = base + s_off;
    ix->post    = (const tt_ix_post *)(const void *)(base + p_off);
    ix->docs    = (const tt_ix_doc *)(const void *)(base + d_off);
    ix->text    = base + x_off;
    ix->n_post  = p_n;
    ix->strings_len = (uint32_t)s_n;
    ix->text_len    = (uint32_t)x_n;
    ix->avgdl   = (double)total_len / (double)ix->n_docs;

    for (uint32_t i = 0; i < ix->n_terms; i++) {
        const tt_ix_term *t = &ix->terms[i];
        if (t->str_off >= s_n || t->post_off > p_n || t->post_n > p_n - t->post_off
            || t->df != t->post_n || !t->df) {
            tt_map_close(&ix->map);
            return tt_fail(".ttindex: term %u points outside the file", i);
        }
        /* The search is a binary search, so ORDER is part of the format and not
         * an implementation detail of the writer.  An unsorted table does not
         * fail: it finds some terms and misses most, and the only symptom is a
         * ranking that is quietly worse.  The writer shipped exactly that bug
         * once, which is why the reader now refuses it. */
        if (i && strcmp(ix->strings + ix->terms[i - 1].str_off,
                        ix->strings + t->str_off) >= 0) {
            tt_map_close(&ix->map);
            return tt_fail(".ttindex: the term table is not sorted at %u "
                           "(\"%s\" then \"%s\") -- rebuild it", i,
                           ix->strings + ix->terms[i - 1].str_off,
                           ix->strings + t->str_off);
        }
    }
    for (uint32_t i = 0; i < ix->n_docs; i++) {
        const tt_ix_doc *d = &ix->docs[i];
        if (d->title_off >= s_n || d->sect_off >= s_n || d->cite_off >= s_n ||
            d->text_off >= x_n  || d->text_len > x_n - d->text_off) {
            tt_map_close(&ix->map);
            return tt_fail(".ttindex: document %u points outside the file", i);
        }
    }
    for (uint64_t i = 0; i < ix->n_post; i++) {
        if (ix->post[i].doc >= ix->n_docs) {
            tt_map_close(&ix->map);
            return tt_fail(".ttindex: posting %llu names document %u of %u",
                           (unsigned long long)i, ix->post[i].doc, ix->n_docs);
        }
    }

    ix->scores = (double *)calloc(ix->n_docs, sizeof(double));
    if (!ix->scores) {
        tt_map_close(&ix->map);
        return tt_fail("out of memory for the score buffer");
    }
    return 0;
}

void tt_index_close(tt_index *ix)
{
    free(ix->scores);
    tt_map_close(&ix->map);
    memset(ix, 0, sizeof(*ix));
}

/* --------------------------------------------------------------- search */

static const tt_ix_term *find_term(const tt_index *ix, const char *t, size_t n)
{
    uint32_t lo = 0, hi = ix->n_terms;
    while (lo < hi) {
        const uint32_t mid = lo + (hi - lo) / 2;
        const char *s = ix->strings + ix->terms[mid].str_off;
        const int c = cmp_str(s, strlen(s), t, n);
        if (c == 0) return &ix->terms[mid];
        if (c < 0) lo = mid + 1; else hi = mid;
    }
    return NULL;
}

typedef struct {
    tt_index *ix;
    double    k1, b;
} scorer;

/* BM25, one query term at a time.
 *
 *   idf = ln(1 + (N - df + 0.5) / (df + 0.5))
 *   contribution = idf * tf * (k1 + 1) / (tf + k1 * (1 - b + b * |D| / avgdl))
 *
 * A term repeated in the query counts twice, because the reference iterates the
 * token LIST and not a set.  It is a rare case and an arguable one, but the
 * ranking the model was trained against is the one with the repetition in it. */
static void score_term(const char *t, size_t n, void *ud)
{
    scorer *sc = (scorer *)ud;
    tt_index *ix = sc->ix;

    const tt_ix_term *e = find_term(ix, t, n);
    if (!e) return;

    const double N   = (double)ix->n_docs;
    const double df  = (double)e->df;
    /* `log(1 + x)` and not `log1p(x)`: they differ in the last bits, and the
     * reference computes the first.  The difference never changes an answer,
     * but it changes which of two near-tied sections is passage [1], and this
     * file exists to rank the way the training data was ranked. */
    const double idf = log(1.0 + (N - df + 0.5) / (df + 0.5));

    for (uint32_t i = 0; i < e->post_n; i++) {
        const tt_ix_post *p = &ix->post[(uint64_t)e->post_off + i];
        const double tf = (double)p->tf;
        const double dl = (double)ix->docs[p->doc].n_terms;
        const double denom = tf + sc->k1 * (1.0 - sc->b + sc->b * dl / ix->avgdl);
        ix->scores[p->doc] += idf * tf * (sc->k1 + 1.0) / denom;
    }
}

int tt_index_search(tt_index *ix, const char *query, tt_hit *out, int max)
{
    if (!ix->n_docs || max <= 0) return 0;

    memset(ix->scores, 0, ix->n_docs * sizeof(double));

    scorer sc;
    sc.ix = ix;
    sc.k1 = 1.5;   /* the constants the training data was retrieved with; */
    sc.b  = 0.75;  /* changing them retrains the model, in effect */
    tt_tokenize(query, strlen(query), score_term, &sc);

    int got = 0;
    while (got < max) {
        int32_t best = -1;
        /* Ascending scan with `>=` picks the HIGHEST index among equal scores,
         * which is what `sorted(..., reverse=True)` over (score, index) does in
         * the reference.  Ties are not hypothetical: two sections quoting the
         * same passage of the term index score identically. */
        for (uint32_t d = 0; d < ix->n_docs; d++) {
            if (ix->scores[d] <= 0.0) continue;
            if (best < 0 || ix->scores[d] >= ix->scores[best]) best = (int32_t)d;
        }
        if (best < 0) break;
        out[got].doc   = best;
        out[got].score = (float)ix->scores[best];
        ix->scores[best] = 0.0;    /* taken; only positives are eligible */
        got++;
    }
    return got;
}

const char *tt_index_title(const tt_index *ix, int32_t doc)
{
    return ix->strings + ix->docs[doc].title_off;
}

const char *tt_index_section(const tt_index *ix, int32_t doc)
{
    return ix->strings + ix->docs[doc].sect_off;
}

const char *tt_index_cite(const tt_index *ix, int32_t doc)
{
    return ix->strings + ix->docs[doc].cite_off;
}

const char *tt_index_text(const tt_index *ix, int32_t doc, uint32_t *len)
{
    if (len) *len = ix->docs[doc].text_len;
    return ix->text + ix->docs[doc].text_off;
}
